{{ config(materialized='view') }}

with t0 as (
    select
        claim_id as HUB_CLAIM_BK__CLAIM_ID,
        genral_remarks
    from {{ ref('stg_hm_bill_detail') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID order by HUB_CLAIM_BK__CLAIM_ID) = 1
),

t1 as (
    select
        nullif(trim(CLAIM_ID),'') as HUB_CLAIM_BK__CLAIM_ID,
        updated_on
    from {{ ref('stg_hm_claim_tracker') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID order by HUB_CLAIM_BK__CLAIM_ID) = 1
),

t2 as (
    select
        claim_id as HUB_CLAIM_BK__CLAIM_ID,
        location_code as HUB_LOCATION_BK__LOCATION_CODE,
        locationcode as HUB_LOCATION_BK__LOCATIONCODE,
        orphan_loc as HUB_LOCATION_BK__ORPHAN_LOC,
        policy_location as HUB_LOCATION_BK__POLICY_LOCATION,
        risk_location as HUB_LOCATION_BK__RISK_LOCATION,
        policy_number as HUB_POLICY_BK__POLICY_NUMBER,
        orphan_close_remark,
        orphan_follow_flag
    from {{ ref('stg_hm_orphan_reg') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID, HUB_POLICY_BK__POLICY_NUMBER order by HUB_CLAIM_BK__CLAIM_ID, HUB_POLICY_BK__POLICY_NUMBER) = 1
),

t3 as (
    select
        claim_id as HUB_CLAIM_BK__CLAIM_ID,
        query_remark
    from {{ ref('stg_hm_query_remark') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__CLAIM_ID order by HUB_CLAIM_BK__CLAIM_ID) = 1
),

t4 as (
    select
        nullif('REMEDINET_REQ:' || nullif(trim(REQUESTID),''), 'REMEDINET_REQ:') as HUB_CLAIM_BK__REMEDINET_REQ_REQUESTID,
        md5(normalise(upper(nullif(coalesce(nullif(trim(ADDRESS1),''),'') || '|' || coalesce(nullif(trim(ADDRESS2),''),'') || '|' || coalesce(nullif(trim(ADDRESS3),''),'') || '|' || coalesce(nullif(trim(CITY),''),'') || '|' || coalesce(nullif(trim(STATE),''),'') || '|' || coalesce(nullif(trim(PIN_CODE),''),''), '|||||')))) as HUB_LOCATION_BK__ADDRESS1_ADDRESS2_ADDRESS3_CITY,
        nullif('MEMBER:' || nullif(trim(MEMBER_NO),''), 'MEMBER:') as HUB_PARTY_BK__MEMBER_MEMBER_NO,
        nullif('MEMBER:' || nullif(trim(MEMBER_NO),''), 'MEMBER:') as HUB_RISK_OBJECT_BK__MEMBER_MEMBER_NO,
        updated_on
    from {{ ref('stg_remedinet_patient_details') }}
    qualify row_number() over (partition by HUB_CLAIM_BK__REMEDINET_REQ_REQUESTID, HUB_LOCATION_BK__ADDRESS1_ADDRESS2_ADDRESS3_CITY, HUB_PARTY_BK__MEMBER_MEMBER_NO, HUB_RISK_OBJECT_BK__MEMBER_MEMBER_NO order by HUB_CLAIM_BK__REMEDINET_REQ_REQUESTID, HUB_LOCATION_BK__ADDRESS1_ADDRESS2_ADDRESS3_CITY, HUB_PARTY_BK__MEMBER_MEMBER_NO, HUB_RISK_OBJECT_BK__MEMBER_MEMBER_NO) = 1
),

t5 as (
    select
        md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|' || coalesce(nullif(trim(CLAIM_ID),''),'') || '|' || coalesce(nullif(trim(RISK_ID),''),''), '||')))) as HUB_ASSESSMENT_BK__CONTRACT_ID_CLAIM_ID_RISK_ID,
        nullif(trim(CLAIM_ID),'') as HUB_CLAIM_BK__CLAIM_ID,
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        updated_by,
        updated_on
    from {{ ref('stg_risk_trans_dtls') }}
    qualify row_number() over (partition by HUB_ASSESSMENT_BK__CONTRACT_ID_CLAIM_ID_RISK_ID, HUB_CLAIM_BK__CLAIM_ID, HUB_POLICY_BK__CONTRACT_ID order by HUB_ASSESSMENT_BK__CONTRACT_ID_CLAIM_ID_RISK_ID, HUB_CLAIM_BK__CLAIM_ID, HUB_POLICY_BK__CONTRACT_ID) = 1
),

t6 as (
    select
        nullif(trim(CONTRACT_ID),'') as HUB_POLICY_BK__CONTRACT_ID,
        nullif('SCHEME:' || nullif(trim(SCHEME_CODE),''), 'SCHEME:') as HUB_PRODUCT_BK__SCHEME_SCHEME_CODE,
        scheme_version
    from {{ ref('stg_ctngy_covers_ext') }}
    qualify row_number() over (partition by HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__SCHEME_SCHEME_CODE order by HUB_POLICY_BK__CONTRACT_ID, HUB_PRODUCT_BK__SCHEME_SCHEME_CODE) = 1
),

t7 as (
    select
        nullif('SCHEME:' || nullif(trim(SCHEME_CODE),''), 'SCHEME:') as HUB_PRODUCT_BK__SCHEME_SCHEME_CODE,
        scheme_version
    from {{ ref('stg_ctngy_scheme_nr_parms') }}
    qualify row_number() over (partition by HUB_PRODUCT_BK__SCHEME_SCHEME_CODE order by HUB_PRODUCT_BK__SCHEME_SCHEME_CODE) = 1
),

t8 as (
    select
        nullif('PARTNER:' || nullif(trim(PARTNER_ID),''), 'PARTNER:') as HUB_PARTY_BK__PARTNER_PARTNER_ID,
        nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|') as HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID,
        scheme_version
    from {{ ref('stg_ctngy_scheme_plans') }}
    qualify row_number() over (partition by HUB_PARTY_BK__PARTNER_PARTNER_ID, HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID order by HUB_PARTY_BK__PARTNER_PARTNER_ID, HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID) = 1
),

t9 as (
    select
        product_code as HUB_PRODUCT_BK__PRODUCT_CODE,
        effective_dt
    from {{ ref('stg_hcs_plansi_mapp') }}
    qualify row_number() over (partition by HUB_PRODUCT_BK__PRODUCT_CODE order by HUB_PRODUCT_BK__PRODUCT_CODE) = 1
)

select
    t5.HUB_ASSESSMENT_BK__CONTRACT_ID_CLAIM_ID_RISK_ID as HUB_ASSESSMENT_BK,
    coalesce(t0.HUB_CLAIM_BK__CLAIM_ID, t1.HUB_CLAIM_BK__CLAIM_ID, t2.HUB_CLAIM_BK__CLAIM_ID, t3.HUB_CLAIM_BK__CLAIM_ID, t4.HUB_CLAIM_BK__REMEDINET_REQ_REQUESTID, t5.HUB_CLAIM_BK__CLAIM_ID) as HUB_CLAIM_BK,
    t4.HUB_LOCATION_BK__ADDRESS1_ADDRESS2_ADDRESS3_CITY as HUB_LOCATION_BK,
    coalesce(t4.HUB_PARTY_BK__MEMBER_MEMBER_NO, t8.HUB_PARTY_BK__PARTNER_PARTNER_ID) as HUB_PARTY_BK,
    coalesce(t2.HUB_POLICY_BK__POLICY_NUMBER, t5.HUB_POLICY_BK__CONTRACT_ID, t6.HUB_POLICY_BK__CONTRACT_ID) as HUB_POLICY_BK,
    coalesce(t6.HUB_PRODUCT_BK__SCHEME_SCHEME_CODE, t7.HUB_PRODUCT_BK__SCHEME_SCHEME_CODE, t8.HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID, t9.HUB_PRODUCT_BK__PRODUCT_CODE) as HUB_PRODUCT_BK,
    t4.HUB_RISK_OBJECT_BK__MEMBER_MEMBER_NO as HUB_RISK_OBJECT_BK,
    t2.HUB_LOCATION_BK__LOCATION_CODE as T2__HUB_LOCATION_BK__LOCATION_CODE,
    t2.HUB_LOCATION_BK__LOCATIONCODE as T2__HUB_LOCATION_BK__LOCATIONCODE,
    t2.HUB_LOCATION_BK__ORPHAN_LOC as T2__HUB_LOCATION_BK__ORPHAN_LOC,
    t2.HUB_LOCATION_BK__POLICY_LOCATION as T2__HUB_LOCATION_BK__POLICY_LOCATION,
    t2.HUB_LOCATION_BK__RISK_LOCATION as T2__HUB_LOCATION_BK__RISK_LOCATION,
    t2.orphan_follow_flag as FOLLOW_UP_REQUIRED_INDICATOR,
    t5.updated_by as LAST_ACTION_BY_USER_REFERENCE,
    coalesce(t1.updated_on, t4.updated_on, t5.updated_on) as LAST_ACTION_DATE,
    coalesce(t0.genral_remarks, t2.orphan_close_remark, t3.query_remark) as NOTE_TEXT,
    t9.effective_dt as VERSION_EFFECTIVE_DATE,
    coalesce(t6.scheme_version, t7.scheme_version, t8.scheme_version) as VERSION_NUMBER
from t0
full outer join t1 on t1.HUB_CLAIM_BK__CLAIM_ID = t0.HUB_CLAIM_BK__CLAIM_ID
full outer join t2 on t2.HUB_CLAIM_BK__CLAIM_ID = coalesce(t0.HUB_CLAIM_BK__CLAIM_ID, t1.HUB_CLAIM_BK__CLAIM_ID)
full outer join t3 on t3.HUB_CLAIM_BK__CLAIM_ID = coalesce(t0.HUB_CLAIM_BK__CLAIM_ID, t1.HUB_CLAIM_BK__CLAIM_ID, t2.HUB_CLAIM_BK__CLAIM_ID)
full outer join t4 on t4.HUB_CLAIM_BK__REMEDINET_REQ_REQUESTID = coalesce(t0.HUB_CLAIM_BK__CLAIM_ID, t1.HUB_CLAIM_BK__CLAIM_ID, t2.HUB_CLAIM_BK__CLAIM_ID, t3.HUB_CLAIM_BK__CLAIM_ID)
full outer join t5 on t5.HUB_CLAIM_BK__CLAIM_ID = coalesce(t0.HUB_CLAIM_BK__CLAIM_ID, t1.HUB_CLAIM_BK__CLAIM_ID, t2.HUB_CLAIM_BK__CLAIM_ID, t3.HUB_CLAIM_BK__CLAIM_ID, t4.HUB_CLAIM_BK__REMEDINET_REQ_REQUESTID)
full outer join t6 on t6.HUB_POLICY_BK__CONTRACT_ID = coalesce(t2.HUB_POLICY_BK__POLICY_NUMBER, t5.HUB_POLICY_BK__CONTRACT_ID)
full outer join t7 on t7.HUB_PRODUCT_BK__SCHEME_SCHEME_CODE = t6.HUB_PRODUCT_BK__SCHEME_SCHEME_CODE
full outer join t8 on t8.HUB_PARTY_BK__PARTNER_PARTNER_ID = t4.HUB_PARTY_BK__MEMBER_MEMBER_NO
full outer join t9 on t9.HUB_PRODUCT_BK__PRODUCT_CODE = coalesce(t6.HUB_PRODUCT_BK__SCHEME_SCHEME_CODE, t7.HUB_PRODUCT_BK__SCHEME_SCHEME_CODE, t8.HUB_PRODUCT_BK__SCHEMEPLAN_SCHEME_CODE_PLAN_ID)
